"use client";

import { X } from "lucide-react";
import { useId, type ComponentProps, type ReactNode } from "react";
import { Button } from "./button";
import { FeedbackIcon, type FeedbackVariant } from "./feedback";
import { cn } from "./lib/cn";
import "./shared/alert.css";
import "./alert.css";

export type AlertProps = Omit<ComponentProps<"div">, "title"> & {
  title: ReactNode;
  variant?: FeedbackVariant;
  loading?: boolean;
  action?: ReactNode;
  onDismiss?: () => void;
};

export function Alert({
  title,
  variant = "neutral",
  loading = false,
  children,
  action,
  onDismiss,
  className,
  ...props
}: AlertProps) {
  const titleId = useId();
  return (
    <div
      data-slot="alert"
      data-variant={loading ? "neutral" : variant}
      role={!loading && variant === "error" ? "alert" : "status"}
      aria-busy={loading || undefined}
      aria-atomic="true"
      aria-labelledby={titleId}
      className={cn(
        "grid min-w-0 grid-cols-[2rem_minmax(0,1fr)_auto] items-start gap-3 rounded-overlay border border-border bg-surface p-4 text-sm text-foreground [overflow-wrap:anywhere]",
        className,
      )}
      {...props}
    >
      <FeedbackIcon variant={variant} loading={loading} />
      <div data-slot="feedback-copy" className="min-w-0 pt-1">
        <div id={titleId} data-slot="feedback-title" className="font-semibold leading-5">
          <span key={loading ? "loading" : variant} data-slot="feedback-message">{title}</span>
        </div>
        {children != null && (
          <div data-slot="feedback-description" className="mt-1 text-sm leading-5 text-muted-foreground">
            <span key={loading ? "loading" : variant} data-slot="feedback-message">{children}</span>
          </div>
        )}
        {action != null && (
          <div data-slot="feedback-action" className="mt-3 flex max-w-full flex-wrap items-center gap-2">
            {action}
          </div>
        )}
      </div>
      {onDismiss && (
        <Button
          variant="ghost"
          size="icon"
          className="-mt-1 -mr-1"
          aria-label="Dismiss alert"
          onClick={onDismiss}
        >
          <X aria-hidden="true" />
        </Button>
      )}
    </div>
  );
}

"use client";

import { Slot, Slottable } from "@radix-ui/react-slot";
import { LoaderCircle } from "lucide-react";
import {
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { cn } from "./lib/cn";
import "./shared/loading-indicator.css";
import "./button.css";

/* Colour, material and press live in button.css keyed on data-variant, so a
   consumer's utility classes still override them. Raised to press: the
   button sinks 1px into an inner shade instead of scaling. */
const variants = {
  default: "",
  secondary: "",
  ghost: "",
  destructive: "",
};

const sizes = {
  sm: "h-8 gap-1.5 rounded-full px-3 text-[13px] max-md:min-h-11 [@media(pointer:coarse)]:min-h-11",
  md: "h-[var(--control-height)] gap-2 rounded-full px-3.5 text-sm",
  lg: "h-11 gap-2 rounded-full px-[18px] text-[15px]",
  icon: "size-[var(--control-height)] rounded-full p-0",
};

export type ButtonProps = ComponentProps<"button"> & {
  variant?: keyof typeof variants;
  size?: keyof typeof sizes;
  asChild?: boolean;
  /** Shows a spinner over the label and swallows clicks while keeping focus and width. */
  loading?: boolean;
  /** Animate a meaningful label/icon change, such as saving → saved. */
  feedbackKey?: string;
};

export function Button({
  className,
  variant = "default",
  size = "md",
  asChild = false,
  loading = false,
  feedbackKey,
  disabled,
  "aria-disabled": ariaDisabled,
  children,
  onClick,
  onClickCapture,
  tabIndex,
  type = "button",
  ...props
}: ButtonProps) {
  const Component = asChild ? Slot : "button";
  const nativeDisabled = Boolean(disabled);
  const blocked =
    nativeDisabled ||
    loading ||
    ariaDisabled === true ||
    ariaDisabled === "true";

  return (
    <Component
      data-slot="button"
      data-variant={variant}
      data-size={size}
      type={asChild ? undefined : type}
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center whitespace-nowrap border border-transparent font-medium tracking-[-0.006em] outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:pointer-events-none aria-disabled:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
        variants[variant],
        sizes[size],
        className,
      )}
      disabled={asChild ? undefined : nativeDisabled}
      aria-disabled={nativeDisabled || ariaDisabled ? true : undefined}
      aria-busy={loading || undefined}
      tabIndex={asChild && nativeDisabled ? -1 : tabIndex}
      {...props}
      onKeyDown={(event) => {
        if (blocked && (event.key === "Enter" || event.key === " ")) {
          event.preventDefault();
        }
        props.onKeyDown?.(event);
      }}
      onClickCapture={(event) => {
        if (blocked) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        onClickCapture?.(event);
      }}
      onClick={onClick}
    >
      {loading && asChild && (
        <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
      )}
      {loading && !asChild && feedbackKey === undefined && (
        <span data-slot="button-busy" aria-hidden="true">
          <LoaderCircle data-slot="loading-indicator" />
        </span>
      )}
      <Slottable>
        {loading && !asChild && feedbackKey === undefined ? (
          <span data-slot="button-label" data-hidden="true">
            {children}
          </span>
        ) : feedbackKey !== undefined && !asChild ? (
          <ButtonFeedback stateKey={feedbackKey}>
            {loading && (
              <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />
            )}
            {children}
          </ButtonFeedback>
        ) : (
          children
        )}
      </Slottable>
    </Component>
  );
}

function ButtonFeedback({
  stateKey,
  children,
}: {
  stateKey: string;
  children: ReactNode;
}) {
  const content = useRef<HTMLSpanElement>(null);
  const [initialKey] = useState(stateKey);
  const [width, setWidth] = useState<number>();
  useLayoutEffect(() => {
    const element = content.current;
    if (!element) return;
    const measure = () => setWidth(element.offsetWidth);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, [stateKey]);
  return (
    <span data-slot="button-feedback" style={{ width }}>
      <span
        key={stateKey}
        ref={content}
        data-slot="button-feedback-label"
        data-enter={stateKey !== initialKey}
      >
        {children}
      </span>
    </span>
  );
}

"use client";

import {
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  type ComponentProps,
} from "react";
import "./checkbox.css";

export type CheckboxProps = Omit<ComponentProps<"input">, "type"> & {
  indeterminate?: boolean;
};

export function Checkbox({
  ref,
  indeterminate = false,
  ...props
}: CheckboxProps) {
  const input = useRef<HTMLInputElement>(null);
  useImperativeHandle(ref, () => input.current!, []);

  // Native activation clears mixed state. Derive this prop from the group's
  // selection; synchronize again whenever the caller renders that state.
  useLayoutEffect(() => {
    if (input.current) input.current.indeterminate = indeterminate;
  });

  return (
    <span data-slot="checkbox-root">
      <input data-slot="checkbox" {...props} type="checkbox" ref={input} />
      <span data-slot="checkbox-indicator" aria-hidden="true">
        <svg viewBox="0 0 12 12" fill="none">
          <path data-mark="check" d="M2.5 6.2 5 8.5l4.5-5" />
          <path data-mark="mixed" d="M3 6h6" />
        </svg>
      </span>
    </span>
  );
}

import { CircleCheck, CircleX, Info, LoaderCircle, TriangleAlert } from "lucide-react";
import "./feedback.css";

export type FeedbackVariant = "neutral" | "success" | "warning" | "error";

const icons = {
  neutral: Info,
  success: CircleCheck,
  warning: TriangleAlert,
  error: CircleX,
};

export function FeedbackIcon({
  variant,
  loading = false,
}: {
  variant: FeedbackVariant;
  loading?: boolean;
}) {
  const Icon = loading ? LoaderCircle : icons[variant];
  return (
    <span data-slot="feedback-icon" aria-hidden="true">
      <span data-slot="feedback-symbol" key={loading ? "loading" : variant}>
        <Icon data-slot={loading ? "loading-indicator" : undefined} />
      </span>
    </span>
  );
}

"use client";
import { CircleAlert, CircleCheck, LoaderCircle } from "lucide-react";
import { useId, type ReactNode } from "react";
import { Label } from "./label";
import { cn } from "./lib/cn";
import "./shared/field-message.css";
import "./shared/loading-indicator.css";
import "./field.css";

export type FieldControlProps = {
  id: string;
  "aria-describedby"?: string;
  "aria-invalid"?: true;
  "aria-required"?: true;
};

export const isEmail = (value: string) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());

/**
 * A label, a control and one message line wired together for assistive
 * technology. Hint, async status and error share the same reserved line and
 * rewrite it in place, so validation never pushes the next field down.
 */
export function Field({
  label,
  description,
  error,
  status,
  statusTone = "pending",
  count,
  required,
  optional,
  action,
  className,
  children,
}: {
  label: string;
  /** Hint shown on the message line until a status or error replaces it. */
  description?: ReactNode;
  /** Replaces the hint and is announced when it appears. */
  error?: string;
  /** An async result such as “Checking availability…” or “Available”. */
  status?: string;
  statusTone?: "pending" | "success";
  /** Right-aligned counter on the message line, e.g. “6 / 40”. */
  count?: string;
  required?: boolean;
  /** Adds "(optional)" after the label. */
  optional?: boolean;
  /** Something aligned with the label, such as a "Forgot password?" link. */
  action?: ReactNode;
  className?: string;
  children: (props: FieldControlProps) => ReactNode;
}) {
  const id = useId();
  const message = `${id}-message`;
  const hasMessage = Boolean(error || status || description || count);
  const tone = error ? "error" : status ? statusTone : "hint";
  return (
    <div data-slot="field" className={cn("grid gap-1.5", className)}>
      <div className="flex items-baseline justify-between gap-3">
        <Label htmlFor={id}>
          {label}
          {optional && <span className="ml-1 font-normal text-muted-foreground">(optional)</span>}
        </Label>
        {action}
      </div>
      {children({
        id,
        "aria-describedby": hasMessage ? message : undefined,
        "aria-invalid": error ? true : undefined,
        "aria-required": required ? true : undefined,
      })}
      <p id={message} data-slot="field-message" data-tone={tone} aria-live={error ? "assertive" : "polite"} role={error ? "alert" : undefined}>
        {tone === "error" && <CircleAlert aria-hidden="true" />}
        {tone === "success" && <CircleCheck aria-hidden="true" />}
        {tone === "pending" && <LoaderCircle data-slot="loading-indicator" aria-hidden="true" />}
        <span data-slot="field-error" className="min-w-0 flex-1">{error ?? status ?? description}</span>
        {count && <span data-slot="field-count">{count}</span>}
      </p>
    </div>
  );
}

import type { ComponentProps, ReactNode } from "react";
import { cn } from "./lib/cn";
import "./shared/input.css";
import "./shared/input-2.css";
import "./shared/input-group.css";
import "./input.css";

const fieldText =
  "w-full min-w-0 text-base text-foreground outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed md:text-sm";

export type InputProps = ComponentProps<"input"> & {
  /** Fixed text or an icon before the value, e.g. "caliper.app/". */
  leading?: ReactNode;
  /** Text, an icon or a status after the value, e.g. a spinner or a count. */
  trailing?: ReactNode;
};

/**
 * A recessed text field. Fields sit slightly below the paper (an inner shade
 * and a 3:1 ring); buttons stand on it, so what you fill and what you press
 * never look alike.
 */
export function Input({ className, leading, trailing, ...props }: InputProps) {
  if (leading === undefined && trailing === undefined) {
    return (
      <input
        data-slot="input"
        className={cn("flex h-[var(--control-height)] rounded-button px-3", fieldText, className)}
        {...props}
      />
    );
  }
  return (
    <span
      data-slot="input-group"
      data-disabled={props.disabled || undefined}
      data-invalid={props["aria-invalid"] === true || props["aria-invalid"] === "true" || undefined}
      data-readonly={props.readOnly || undefined}
      className={cn("flex h-[var(--control-height)] w-full min-w-0 items-center gap-2 rounded-button px-3", className)}
    >
      {leading !== undefined && <span data-slot="input-affix">{leading}</span>}
      <input data-slot="input-bare" className={cn("h-full flex-1 bg-transparent", fieldText)} {...props} />
      {trailing !== undefined && <span data-slot="input-trailing">{trailing}</span>}
    </span>
  );
}

import type { ComponentProps } from "react";
import { cn } from "./lib/cn";

export function Label({ className, ...props }: ComponentProps<"label">) {
  return (
    <label
      data-slot="label"
      className={cn(
        "inline-block max-w-full text-sm leading-5 font-medium [overflow-wrap:anywhere]",
        className,
      )}
      {...props}
    />
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import { Eye } from "lucide-react";
import { useId, useState, type ComponentProps } from "react";
import { Input } from "./input";
import { Label } from "./label";
import { cn } from "./lib/cn";
import "./shared/chip-option.css";
import "./password-field.css";

export function PasswordField({
  label,
  description,
  id,
  messages,
  className,
  onFocus,
  onBlur,
  onKeyUp,
  ...props
}: {
  label: string;
  description?: string;
  messages?: { show?: string; hide?: string };
} & Omit<ComponentProps<"input">, "type">) {
  const generated = useId();
  const fieldId = id ?? generated;
  const descriptionId = `${fieldId}-description`;
  const capsId = `${fieldId}-caps`;
  const [visible, setVisible] = useState(false);
  const [caps, setCaps] = useState(false);
  const [focused, setFocused] = useState(false);
  const show = messages?.show ?? "Show password";
  const hide = messages?.hide ?? "Hide password";
  const describedBy = [description ? descriptionId : null, focused && caps ? capsId : null].filter(Boolean).join(" ") || undefined;

  return (
    <div className={cn("grid content-start gap-1.5", className)}>
      <Label htmlFor={fieldId}>{label}</Label>
      <div className="relative">
        <Input
          {...props}
          id={fieldId}
          type={visible ? "text" : "password"}
          spellCheck={false}
          autoCapitalize="off"
          autoCorrect="off"
          aria-describedby={describedBy}
          className="pr-11"
          onFocus={(event) => {
            setFocused(true);
            onFocus?.(event);
          }}
          onBlur={(event) => {
            setFocused(false);
            onBlur?.(event);
          }}
          onKeyUp={(event) => {
            setCaps(event.getModifierState("CapsLock"));
            onKeyUp?.(event);
          }}
        />
        <button
          data-slot="password-toggle"
          type="button"
          aria-pressed={visible}
          aria-label={visible ? hide : show}
          className="absolute top-1/2 right-1 grid size-8 -translate-y-1/2 place-items-center rounded-control text-muted-foreground outline-none hover:text-foreground focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
          onClick={() => setVisible((value) => !value)}
        >
          <span className="relative grid size-4 place-items-center">
            <Eye aria-hidden="true" className="size-4" />
            <span data-slot="password-slash" data-drawn={!visible} />
          </span>
        </button>
      </div>
      {description ? (
        <p id={descriptionId} className="text-xs leading-[18px] text-muted-foreground">
          {description}
        </p>
      ) : null}
      <p id={capsId} role="status" className={cn("text-xs leading-[18px] text-warning", !(focused && caps) && "sr-only")}>
        {focused && caps ? "Caps Lock is on." : ""}
      </p>
    </div>
  );
}

"use client";
import { useEffect, useRef, useState, type FormEvent, type ReactNode } from "react";
import { Alert } from "./alert";
import { Button } from "./button";
import { Checkbox } from "./checkbox";
import { Field, isEmail } from "./field";
import { Input } from "./input";
import { Label } from "./label";
import { cn } from "./lib/cn";
import { PasswordField } from "./password-field";

export type AuthProvider = { id: string; label: string; icon?: ReactNode; onClick: () => void };
export type SignInResult = void | { error?: string; fields?: { email?: string; password?: string } };

export function Providers({ providers, disabled, verb = "Continue with" }: { providers: readonly AuthProvider[]; disabled?: boolean; verb?: string }) {
  return (
    <div className="grid gap-2">
      <div className="grid gap-2">
        {providers.map((p) => (
          <Button key={p.id} type="button" variant="secondary" disabled={disabled} onClick={p.onClick}>
            {p.icon}
            {verb} {p.label}
          </Button>
        ))}
      </div>
      <div role="separator" aria-label="or" className="flex items-center gap-3 text-xs text-muted-foreground before:h-px before:flex-1 before:bg-border after:h-px after:flex-1 after:bg-border">
        or
      </div>
    </div>
  );
}

/** Email and password sign in with inline validation, a server error area and optional single sign-on buttons. */
export function SignInForm({
  title = "Sign in",
  description,
  onSubmit,
  providers,
  forgotHref,
  onForgot,
  signUp,
  rememberMe = true,
  defaultEmail = "",
  className,
}: {
  title?: string;
  description?: string;
  onSubmit: (values: { email: string; password: string; remember: boolean }) => Promise<SignInResult> | SignInResult;
  providers?: readonly AuthProvider[];
  forgotHref?: string;
  onForgot?: () => void;
  /** Where people without an account go. */
  signUp?: { href?: string; onClick?: () => void };
  rememberMe?: boolean;
  defaultEmail?: string;
  className?: string;
}) {
  const [values, setValues] = useState({ email: defaultEmail, password: "", remember: true });
  const [touched, setTouched] = useState({ email: false, password: false });
  const [server, setServer] = useState<{ error?: string; fields?: { email?: string; password?: string } }>({});
  const [pending, setPending] = useState(false);
  const form = useRef<HTMLFormElement>(null);
  const refocus = useRef<string | null>(null);
  // Fields are disabled while sending; move focus to the first problem once they can take it.
  useEffect(() => {
    if (pending || !refocus.current) return;
    form.current?.querySelector<HTMLElement>(`[name="${refocus.current}"]`)?.focus();
    refocus.current = null;
  }, [pending]);

  const local = {
    email: !values.email.trim() ? "Enter your email address." : !isEmail(values.email) ? "Enter a valid email address, like name@example.com." : "",
    password: !values.password ? "Enter your password." : "",
  };
  const errors = {
    email: (touched.email && local.email) || server.fields?.email || "",
    password: (touched.password && local.password) || server.fields?.password || "",
  };

  const submit = async (event: FormEvent) => {
    event.preventDefault();
    if (pending) return;
    setTouched({ email: true, password: true });
    setServer({});
    const first = local.email ? "email" : local.password ? "password" : null;
    if (first) {
      form.current?.querySelector<HTMLElement>(`[name="${first}"]`)?.focus();
      return;
    }
    setPending(true);
    let target: string | null = null;
    try {
      const result = await onSubmit({ email: values.email.trim(), password: values.password, remember: values.remember });
      if (result && (result.error || result.fields)) {
        setServer(result);
        target = result.fields?.email ? "email" : result.fields?.password ? "password" : null;
      }
    } catch (error) {
      setServer({ error: error instanceof Error ? error.message : "Something went wrong. Try again." });
    } finally {
      setPending(false);
    }
    if (target) refocus.current = target;
  };

  return (
    <form ref={form} noValidate data-slot="sign-in-form" aria-label={title} onSubmit={submit} className={cn("grid gap-5", className)}>
      <div className="grid gap-1">
        <h1 className="text-xl font-semibold tracking-tight">{title}</h1>
        {description && <p className="text-sm text-muted-foreground">{description}</p>}
      </div>
      {server.error && (
        <Alert variant="error" title={server.error} />
      )}
      {providers && providers.length > 0 && <Providers providers={providers} disabled={pending} />}
      <Field label="Email" error={errors.email} required>
        {(control) => (
          <Input
            {...control}
            name="email"
            type="email"
            inputMode="email"
            autoComplete="username"
            autoCapitalize="none"
            spellCheck={false}
            value={values.email}
            disabled={pending}
            onChange={(e) => {
              setValues({ ...values, email: e.target.value });
              if (server.fields?.email || server.error) setServer({});
            }}
            onBlur={() => setTouched((t) => ({ ...t, email: true }))}
          />
        )}
      </Field>
      <div className="grid gap-1.5">
        <div className="relative">
          <PasswordField
            label="Password"
            name="password"
            autoComplete="current-password"
            required
            aria-invalid={errors.password ? true : undefined}
            value={values.password}
            disabled={pending}
            onChange={(e) => {
              setValues({ ...values, password: e.target.value });
              if (server.fields?.password || server.error) setServer({});
            }}
            onBlur={() => setTouched((t) => ({ ...t, password: true }))}
          />
          {(forgotHref || onForgot) && (
            <a
              href={forgotHref ?? "#"}
              onClick={(event) => {
                if (onForgot) {
                  event.preventDefault();
                  onForgot();
                }
              }}
              className="absolute right-0 top-0 rounded-control text-xs text-muted-foreground underline underline-offset-4 outline-none hover:text-foreground focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
            >
              Forgot password?
            </a>
          )}
        </div>
        {errors.password && (
          <p role="alert" className="text-xs leading-[18px] text-danger">
            {errors.password}
          </p>
        )}
      </div>
      {rememberMe && (
        <div className="flex items-center gap-2">
          <Checkbox id="remember" checked={values.remember} disabled={pending} onChange={(e) => setValues({ ...values, remember: e.target.checked })} />
          <Label htmlFor="remember" className="font-normal">
            Keep me signed in on this device
          </Label>
        </div>
      )}
      <Button type="submit" loading={pending} className="w-full">
        {pending ? "Signing in…" : "Sign in"}
      </Button>
      {signUp && (
        <p className="text-center text-sm text-muted-foreground">
          No account yet?{" "}
          <a
            href={signUp.href ?? "#"}
            onClick={(event) => {
              if (signUp.onClick) {
                event.preventDefault();
                signUp.onClick();
              }
            }}
            className="rounded-control font-medium text-foreground underline underline-offset-4 outline-none focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
          >
            Create one
          </a>
        </p>
      )}
    </form>
  );
}

/* Shared by alert.tsx, toast.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
