/* button.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="button"] {
    transition-property: background-color, color, border-color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-out);
  }

  /* Button material. Raised to press: a lit top edge and a small lift; the
     press travels 1px down and swaps the lift for an inner shade. Only
     translate animates (release on the settle curve); shadows swap. */
  [data-slot="button"] {
    --b-bg: var(--raised);
    --b-bg-hover: var(--raised-hover);
    --b-bg-press: var(--raised-press);
    --b-fg: var(--foreground);
    --b-shadow: var(--shadow-raised);
    --b-shadow-press: var(--shadow-raised-press);
    background-color: var(--b-bg);
    color: var(--b-fg);
    box-shadow: var(--b-shadow);
    transition-property: background-color, color, border-color, translate, scale;
    transition-duration:
      var(--duration-fast), var(--duration-fast), var(--duration-fast),
      var(--duration-normal), var(--duration-normal);
    transition-timing-function:
      var(--ease-out), var(--ease-out), var(--ease-out), var(--ease-settle),
      var(--ease-settle);
  }
  [data-slot="button"][data-variant="default"] {
    --b-bg: var(--primary);
    --b-bg-hover: var(--primary-hover);
    --b-bg-press: var(--primary-press);
    --b-fg: var(--primary-foreground);
    --b-shadow: var(--shadow-accent);
    --b-shadow-press: var(--shadow-accent-press);
  }
  [data-slot="button"][data-variant="destructive"] {
    --b-bg: var(--danger-fill);
    --b-bg-hover: var(--danger-fill-hover);
    --b-bg-press: var(--danger-fill-press);
    --b-fg: var(--danger-fill-foreground);
    --b-shadow: var(--shadow-danger);
    --b-shadow-press: var(--shadow-danger-press);
  }
  [data-slot="button"][data-variant="ghost"] {
    --b-bg: transparent;
    --b-bg-hover: var(--muted);
    --b-bg-press: var(--muted);
    --b-fg: var(--muted-foreground);
    --b-shadow: none;
    --b-shadow-press: none;
  }
  @media (hover: hover) {
    [data-slot="button"]:hover {
      background-color: var(--b-bg-hover);
    }
    [data-slot="button"][data-variant="ghost"]:hover {
      color: var(--foreground);
    }
  }
  [data-slot="button"]:active:not(:disabled):not([aria-disabled="true"]):not(
      [aria-busy="true"]
    ) {
    translate: 0 var(--motion-press-travel);
    scale: var(--motion-press-scale);
    background-color: var(--b-bg-press);
    box-shadow: var(--b-shadow-press);
    transition-duration:
      var(--duration-fast), var(--duration-fast), var(--duration-fast), 90ms,
      90ms;
    transition-timing-function: var(--ease-out);
  }
  [data-slot="button"]:is(:disabled, [aria-disabled="true"]):not([aria-busy="true"]) {
    background-color: var(--sunken);
    color: var(--muted-foreground);
  }
  [data-slot="button"][data-variant="ghost"]:is(:disabled, [aria-disabled="true"]):not(
      [aria-busy="true"]
    ) {
    background-color: transparent;
    box-shadow: none;
  }
  /* Loading keeps the exact width: the label stays in flow but invisible. */
  [data-slot="button-label"] {
    display: inline-flex;
    align-items: center;
    gap: inherit;
  }
  /* Opacity, not visibility, so the label still names the button. */
  [data-slot="button-label"][data-hidden="true"] {
    opacity: 0;
  }
  [data-slot="button-busy"] {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
  }
  [data-slot="button-feedback"] {
    display: inline-flex;
    align-items: center;
    gap: inherit;
    overflow: clip;
    transition: width var(--duration-normal) var(--ease-out);
  }
  [data-slot="button-feedback-label"] {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    gap: inherit;
    width: max-content;
  }
  [data-slot="button-feedback-label"][data-enter="true"] {
    animation: caliper-feedback-enter var(--duration-normal) var(--ease-out);
  }

  [data-slot="button"][aria-busy="true"] {
    pointer-events: none;
  }
  [data-slot="button"][data-action-phase="error"] {
    color: var(--danger);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="button"],
    [data-slot="button-feedback"] {
      transition: none;
    }
    [data-slot="button"]:active:not(:disabled):not([aria-disabled="true"]):not(
        [aria-busy="true"]
      ) {
      translate: none;
    }
    [data-slot="button-feedback-label"],
    [data-slot="button-feedback-label"][data-enter="true"] {
      animation: none;
    }
  }

  /* Toggle: pressed is recessed, as a toggled tool in a button group is. */
  /* Four attributes, so it wins over the group and toolbar pressed rules in any stylesheet order. */
  [data-slot="button"][data-variant="ghost"][data-toggle][aria-pressed="true"] {
    --b-bg: var(--sunken);
    --b-bg-hover: var(--sunken);
    --b-bg-press: var(--sunken);
    --b-fg: var(--foreground);
    --b-shadow: var(--shadow-sunken);
    --b-shadow-press: var(--shadow-sunken);
  }
}

/* checkbox.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* The native input fills the target; the smaller indicator is decorative. */
  [data-slot="checkbox-root"] {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    width: var(--control-height);
    height: var(--control-height);
    vertical-align: middle;
  }

  [data-slot="checkbox"] {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    margin: 0;
    appearance: none;
    border: 0;
    background: transparent;
    outline: none;
    cursor: pointer;
    touch-action: manipulation;
  }

  /* Choice marks: one 18px recessed mark for checkbox and radio. Checked
     marks fill with ink; the check stroke draws itself and the radio dot
     settles in. The switch thumb stretches while pressed, then settles. */
  [data-slot="checkbox-indicator"] {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: center;
    pointer-events: none;
    background: var(--field);
    box-shadow: var(--shadow-field);
    transition:
      background-color var(--duration-fast) var(--ease-out),
      box-shadow var(--duration-fast) var(--ease-out);
  }

  [data-slot="checkbox-indicator"] {
    width: 18px;
    height: 18px;
  }

  [data-slot="checkbox-indicator"] {
    border-radius: var(--radius-mark);
    color: var(--accent-foreground);
  }
  [data-slot="checkbox-indicator"] svg {
    width: 12px;
    height: 12px;
    stroke: currentColor;
    stroke-width: 2;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  [data-slot="checkbox-indicator"] path {
    stroke-dasharray: 20;
    stroke-dashoffset: 20;
    transition: stroke-dashoffset 200ms var(--ease-out);
  }
  [data-slot="checkbox"]:checked:not(:indeterminate) + [data-slot="checkbox-indicator"] [data-mark="check"],
  [data-slot="checkbox"]:indeterminate + [data-slot="checkbox-indicator"] [data-mark="mixed"] {
    stroke-dashoffset: 0;
  }

  [data-slot="checkbox"]:checked + [data-slot="checkbox-indicator"],
  [data-slot="checkbox"]:indeterminate + [data-slot="checkbox-indicator"] {
    background: var(--accent);
    box-shadow: 0 0 0 1px var(--accent), inset 0 1px 0 rgb(255 255 255 / 14%);
  }

  @media (hover: hover) {
    [data-slot="checkbox"]:hover:not(:disabled):not(:checked)
      + [data-slot="checkbox-indicator"] {
      box-shadow: var(--shadow-field-hover);
    }
  }

  [data-slot="checkbox"]:focus-visible + [data-slot="checkbox-indicator"] {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }

  [data-slot="checkbox"][aria-invalid="true"]
    + [data-slot="checkbox-indicator"] {
    box-shadow: var(--shadow-field-invalid);
    outline-color: var(--destructive);
  }

  [data-slot="checkbox"]:disabled {
    cursor: not-allowed;
  }
  [data-slot="checkbox"]:disabled + [data-slot="checkbox-indicator"] {
    background: var(--sunken);
    box-shadow: var(--shadow-field-quiet);
    color: var(--muted-foreground);
  }
  [data-slot="checkbox"]:disabled:is(:checked, :indeterminate) + [data-slot="checkbox-indicator"] {
    background: var(--border);
    box-shadow: none;
  }

  @media (forced-colors: active) {
    [data-slot="checkbox-indicator"] {
      forced-color-adjust: none;
      background: Canvas;
      border-color: CanvasText;
    }
    [data-slot="checkbox"]:checked + [data-slot="checkbox-indicator"],
    [data-slot="checkbox"]:indeterminate + [data-slot="checkbox-indicator"] {
      background: Highlight;
      border-color: Highlight;
    }
    [data-slot="checkbox"]:is(:checked, :indeterminate) + [data-slot="checkbox-indicator"] {
      color: HighlightText;
    }
    [data-slot="checkbox-indicator"] {
      border: 1px solid CanvasText;
      box-shadow: none;
    }
    [data-slot="checkbox"]:hover:not(:disabled)
      + [data-slot="checkbox-indicator"] {
      border-color: CanvasText;
    }
    [data-slot="checkbox"]:focus-visible + [data-slot="checkbox-indicator"] {
      outline-color: Highlight;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="checkbox-indicator"],
    [data-slot="checkbox-indicator"] path {
      transition: none;
    }
  }
}

